parts.text:
{
  "units": [
    {
      "quote": "The permittee conducting surface coal mining and reclamation operations on natural slopes that exceed 20 degrees, or on lesser slopes that require measures to protect the area from disturbance, as determined by the regulatory authority after consideration of soils, climate, the method of operation, geology, and other regional characteristics, shall meet the following performance standards.",
      "scope_quotes": [],
      "kind": "requirement",
      "meaning": "Permittees conducting surface coal mining and reclamation operations must satisfy the performance standards of this section when operating on natural slopes exceeding 20 degrees, or on lesser slopes where the regulatory authority determines that measures are required to protect the area from disturbance based on consideration of soils, climate, operating method, geology, and other regional characteristics."
    },
    {
      "quote": "The standards of this section do not apply where mining is done on a flat or gently rolling terrain with an occasional steep slope through which the mining proceeds and leaves a plain or predominantly flat area;",
      "scope_quotes": [],
      "kind": "exemption",
      "meaning": "The performance standards of this section do not apply to mining conducted on flat or gently rolling terrain that features an occasional steep slope through which mining proceeds and leaves behind a plain or predominantly flat area."
    },
    {
      "quote": "or where the mining is governed by § 716.3.",
      "scope_quotes": [
        "The standards of this section do not apply"
      ],
      "kind": "exemption",
      "meaning": "The performance standards of this section do not apply when the mining operations are governed by 30 CFR § 716.3."
    },
    {
      "quote": "Spoil, waste materials or debris, including that from clearing and grubbing, and abandoned or disabled equipment, shall not be placed or allowed to remain on the downslope.",
      "scope_quotes": [
        "The permittee conducting surface coal mining and reclamation operations on natural slopes that exceed 20 degrees, or on lesser slopes that require measures to protect the area from disturbance, as determined by the regulatory authority after consideration of soils, climate, the method of operation, geology, and other regional characteristics, shall meet the following performance standards."
      ],
      "kind": "prohibition",
      "meaning": "On applicable steep slope or regulatory-designated operations, spoil, waste materials, debris (including clearing and grubbing debris), and abandoned or disabled equipment are prohibited from being placed or left to remain on the downslope."
    },
    {
      "quote": "The highwall shall be completely covered with spoil and the disturbed are a graded to comply with the provisions of § 715.14 of this chapter.",
      "scope_quotes": [
        "The permittee conducting surface coal mining and reclamation operations on natural slopes that exceed 20 degrees, or on lesser slopes that require measures to protect the area from disturbance, as determined by the regulatory authority after consideration of soils, climate, the method of operation, geology, and other regional characteristics, shall meet the following performance standards."
      ],
      "kind": "requirement",
      "meaning": "On applicable operations, the highwall must be entirely covered with spoil, and the disturbed area must be graded in compliance with the provisions of 30 CFR § 715.14."
    },
    {
      "quote": "Land above the highwall shall not be disturbed unless the regulatory authority finds that the disturbance will facilitate compliance with the requirements of this section.",
      "scope_quotes": [
        "The permittee conducting surface coal mining and reclamation operations on natural slopes that exceed 20 degrees, or on lesser slopes that require measures to protect the area from disturbance, as determined by the regulatory authority after consideration of soils, climate, the method of operation, geology, and other regional characteristics, shall meet the following performance standards."
      ],
      "kind": "prohibition",
      "meaning": "Disturbance of land located above the highwall is prohibited during applicable operations, unless the regulatory authority expressly finds that such disturbance will facilitate compliance with the requirements of this section."
    },
    {
      "quote": "Material in excess of that required to meet the provisions of § 715.14 of this chapter shall be disposed of in accordance with the requirements of § 715.15 of this chapter.",
      "scope_quotes": [
        "The permittee conducting surface coal mining and reclamation operations on natural slopes that exceed 20 degrees, or on lesser slopes that require measures to protect the area from disturbance, as determined by the regulatory authority after consideration of soils, climate, the method of operation, geology, and other regional characteristics, shall meet the following performance standards."
      ],
      "kind": "requirement",
      "meaning": "Any material exceeding the amount needed to satisfy 30 CFR § 715.14 must be disposed of pursuant to the requirements of 30 CFR § 715.15."
    },
    {
      "quote": "Woody materials may be buried in the backfilled area only when burial does not cause, or add to, instability of the backfill.",
      "scope_quotes": [
        "The permittee conducting surface coal mining and reclamation operations on natural slopes that exceed 20 degrees, or on lesser slopes that require measures to protect the area from disturbance, as determined by the regulatory authority after consideration of soils, climate, the method of operation, geology, and other regional characteristics, shall meet the following performance standards."
      ],
      "kind": "permission",
      "meaning": "Woody materials are permitted to be buried within the backfilled area if and only if the burial does not cause or increase instability in the backfill."
    },
    {
      "quote": "Woody materials may be chipped and distributed through the backfill when approved by the regulatory authority.",
      "scope_quotes": [
        "The permittee conducting surface coal mining and reclamation operations on natural slopes that exceed 20 degrees, or on lesser slopes that require measures to protect the area from disturbance, as determined by the regulatory authority after consideration of soils, climate, the method of operation, geology, and other regional characteristics, shall meet the following performance standards."
      ],
      "kind": "permission",
      "meaning": "Woody materials are permitted to be chipped and distributed throughout the backfill provided that prior approval is obtained from the regulatory authority."
    }
  ]
}
